import{_ as e,o as l,c as i,at as t}from"./chunks/framework.CY22Hent.js";const s=JSON.parse('{"title":"系统分析师笔记02_数学与工程基础","description":"","frontmatter":{"title":"系统分析师笔记02_数学与工程基础","date":"2026-08-10T00:00:00.000Z","lastUpdated":"2026-08-10T00:00:00.000Z","categories":["软考"],"tags":["软考"]},"headers":[],"relativePath":"blogs/软考/系统分析师笔记02_数学与工程基础.md","filePath":"blogs/软考/系统分析师笔记02_数学与工程基础.md"}'),p={name:"blogs/软考/系统分析师笔记02_数学与工程基础.md"};function o(r,a,h,n,d,u){return l(),i("div",null,[...a[0]||(a[0]=[t('<p>[toc]</p><h1 id="系统分析师笔记02-数学与工程基础" tabindex="-1">系统分析师笔记02_数学与工程基础 <a class="header-anchor" href="#系统分析师笔记02-数学与工程基础" aria-label="Permalink to &quot;系统分析师笔记02_数学与工程基础&quot;">​</a></h1><p>该笔记内容来自《系统分析师教程》第2版。</p><p>数学是一门严谨、缜密的学科，学习应用数学知识，可以培养系统分析师的抽象思维能力和逻辑推理能力，使其在从事系统分析工作时思路清晰，在复杂、紊乱的现象中把握住事物的本质。</p><p>在工程领域，系统分析师需要具备一定的工程基础知识，以便能够理解和分析复杂系统的工程方面的问题，并能够与工程师和其他工程专业人员沟通和协作，以实现系统的成功实施和运营。</p><h2 id="数学统计基础" tabindex="-1">数学统计基础 <a class="header-anchor" href="#数学统计基础" aria-label="Permalink to &quot;数学统计基础&quot;">​</a></h2><p>学习概率论与数理统计，可以培养系统分析师以随机观点来理解丰富多彩的现实世界的思维，形成数学思考和分析的意识，提高解决问题的能力。</p><h3 id="古典概率应用" tabindex="-1">古典概率应用 <a class="header-anchor" href="#古典概率应用" aria-label="Permalink to &quot;古典概率应用&quot;">​</a></h3><p>人们在客观世界中所观察到的现象大致可以分为两类:一类是在一定条件下必然发生的，这类现象是可以事前预言的，其结果是确定的，称为确定性现象或必然现象;</p><p>另一类是在一定条件下可能发生也可能不发生，这类现象在观察之前无法预知它的准确结果，称为随机现象。</p><h2 id="图论应用" tabindex="-1">图论应用 <a class="header-anchor" href="#图论应用" aria-label="Permalink to &quot;图论应用&quot;">​</a></h2><p>在现实世界中，有很多现象、事物、状态都可以用图形来描述，许多学科都以图论作为工具来研究和解决问题。例如，在软件开发中，各项任务之间怎么衔接，才能使开发工作完成得既快又好。</p><p>在信息系统建设中，将庞大而复杂的信息系统工程和管理问题用图来描述，可以解决很多工程设计和管理决策的最优化问题，例如，完成工程任务的时间最少、费用最省等。</p><h3 id="最小生成树" tabindex="-1">最小生成树 <a class="header-anchor" href="#最小生成树" aria-label="Permalink to &quot;最小生成树&quot;">​</a></h3><p>在连通的带权图的所有生成树中，权值和最小的生成树(包含图中所有顶点的树)，称作最小生成树。</p><p>求带权连通无向图的最小生成树的算法有普里姆(Prim)算法、克鲁斯卡尔(Kruskal)算法、博鲁夫卡(Boruvka)算法和反向删除(Reverse-Delete)算法等。</p><h3 id="最短路径" tabindex="-1">最短路径 <a class="header-anchor" href="#最短路径" aria-label="Permalink to &quot;最短路径&quot;">​</a></h3><p>带权图的最短路径问题即求两个顶点间长度最短的路径。</p><p>其中路径长度不是指路径上边数的总和，而是指路径上各边的权值总和。路径长度的具体含义取决于边上权值所代表的意义。</p><h3 id="网络与最大流量" tabindex="-1">网络与最大流量 <a class="header-anchor" href="#网络与最大流量" aria-label="Permalink to &quot;网络与最大流量&quot;">​</a></h3><p>许多应用中包含流量问题。例如，公路系统中有车辆流，控制系统中有信息流，网络系统中有数据流，金融系统中有现金流等。在实际应用中，很多时候需要求解最大流量问题。</p><h2 id="预测与决策" tabindex="-1">预测与决策 <a class="header-anchor" href="#预测与决策" aria-label="Permalink to &quot;预测与决策&quot;">​</a></h2><p>预测是指对事物的演化预先做出的科学推测。</p><p>广义的预测既包括在同一时期根据已知事物推测未知事物的静态预测，也包括根据某一事物的历史和现状推测其未来的动态预测。狭义的预测仅指动态预测，也就是对事物的未来演化预先做出的科学推测。</p><p>预测在系统分析师的工作中占据着重要的地位。通过对历史数据和当前现状进行分析，系统分析师可以预测未来的趋势和变化。这些预测可以用于制定决策，例如制订战略计划、优化业务流程、改进营销策略、提高生产效率等。系统分析师还可以使用预测来进行风险评估，以确定企业或组织可能面临的风险和机遇。</p><p>总之，预测和系统分析师是密不可分的。预测为系统分析师提供了一种有效的工具，可以帮助他们更好地了解企业或组织的运营情况和未来发展趋势，从而做出更明智的决策。</p><h3 id="预测的基本内涵" tabindex="-1">预测的基本内涵 <a class="header-anchor" href="#预测的基本内涵" aria-label="Permalink to &quot;预测的基本内涵&quot;">​</a></h3><p>科学的预测通常是在对所研究系统进行深入分析的基础上，建立数学模型，运用数学模型获得所需要的预测结论。</p><p>必须指出的是，有时候所建立的数学模型未必能正确地反映系统的发展变化规律，或许会得出错误的预测结果。</p><h3 id="预测的程序" tabindex="-1">预测的程序 <a class="header-anchor" href="#预测的程序" aria-label="Permalink to &quot;预测的程序&quot;">​</a></h3><p>为保证预测工作顺利进行，必须有组织有计划地安排其工作进程，以期取得应有的成效。</p><p>预测的程序或步骤如下所述:</p><ul><li><p>(1) 明确预测任务、制订预测计划是首先要解决的问题。明确预测任务，就是从决策与管理的需求出发，紧密联系实际需要，确定预测要解决的问题。预测计划是根据预测任务制订的预测方案，包括预测的内容、项目，预测所需要的资料，准备选用的预测方法，预测的进程和完成时间，编制预测的预算，调配力量，组织实施等。</p></li><li><p>(2) 搜集、审核和整理资料。准确无误的调查统计资料和信息是预测的基础。进行预测需要有大量的历史数据，掌握与预测目的、内容有关的各种历史资料，以及影响未来发展的现实资料，即要从多方面搜集资料。</p><ul><li>筛选资料的标准有三个:1直接有关性;2可靠性;3最新性。把符合这三点的资料搜集到之后，经过分析研究，有必要时再搜集其他有关资料。</li></ul></li><li><p>(3) 选择预测方法和建立数学模型。在掌握资料的基础上，进一步选择适当的预测方法和建立数学模型，这是提高预测准确性的关键步骤。</p></li><li><p>(4) 检验模型。预测模型建立之后必须经过检验才能用于预测。模型检验主要包括考查参数估计值在理论上是否有意义，统计显著性如何，模型是否具有良好的超样本特性</p></li><li><p>(5) 分析预测误差，评价预测结果，即分析预测值偏离实际值的程度及其产生的原因。如果预测误差未超出允许的范围，即认为模型的预测功效合乎要求，否则，就需要查找原因，对模型进行修正和调整。</p></li><li><p>(6) 最后向决策者提交预测报告。</p></li></ul><h3 id="决策的概念和过程" tabindex="-1">决策的概念和过程 <a class="header-anchor" href="#决策的概念和过程" aria-label="Permalink to &quot;决策的概念和过程&quot;">​</a></h3><p>决策是指在一定的条件下，从多种可供选择的方案中选择一个方案来达到特定的目标或目的的过程。</p><p>决策是系统分析师工作中的一个重要方面。系统分析师需要在分析和解决问题的过程中做出决策，他们需要对不同方案进行评估和比较，以选择最佳方案来解决问题。</p><p>因此，系统分析师需要具备良好的决策能力，以便在工作中做出明智的决策。同时，他们还需要掌握一系列工具和技术，例如流程图、数据建模、系统分析和设计等，以支持决策过程。</p><h2 id="数学建模" tabindex="-1">数学建模 <a class="header-anchor" href="#数学建模" aria-label="Permalink to &quot;数学建模&quot;">​</a></h2><p>当需要从定量的角度分析和研究一个实际问题时，人们就要在深入调查研究、了解对象信息、做出简化假设、分析内在规律等工作的基础上，用数学的符号和语言，把它表述为数学式子，也就是数学模型，然后用通过计算得到的模型结果来解释实际问题，并接受实际的检验。这个建立数学模型的全过程就称为数学建模。</p><h3 id="数学建模的基本方法" tabindex="-1">数学建模的基本方法 <a class="header-anchor" href="#数学建模的基本方法" aria-label="Permalink to &quot;数学建模的基本方法&quot;">​</a></h3><p>一般的建模方法和思路有以下4种:</p><ul><li>(1)直接分析法:根据对问题内在机理的认识，直接构造出模型。</li><li>(2)类比法:根据类似问题的模型构造新模型。</li><li>(3)数据分析法:通过试验，获得与问题密切相关的大量数据，用统计分析方法进行建模。</li><li>(4)构想法:对将来可能发生的情况给出逻辑上合理的设想和描述，然后用己有的方法构造模型，并不断修正完善，直至比较满意为止。</li></ul><h3 id="数学建模的特点和分类" tabindex="-1">数学建模的特点和分类 <a class="header-anchor" href="#数学建模的特点和分类" aria-label="Permalink to &quot;数学建模的特点和分类&quot;">​</a></h3><p>数学模型可以按照不同的方式分类，下面介绍几种常用的分类方法。</p><blockquote><p>按照模型的应用领域分类</p></blockquote><p>按照应用领域不同，可对模型进行分类，如人口模型、交通模型、环境模型、城镇规划模型、水资源模型等。范畴更大一些则形成许多边缘学科，如生物数学、医学数学、地质数学、数量经济学、数学社会学等。</p><blockquote><p>按照建立模型的数学方法分类</p></blockquote><p>按照建立模型的数学方法(或所属数学分支)不同，可对模型进行分类，如初等模型、几何模型、微分方程模型、统计回归模型、数学规划模型等。</p><blockquote><p>按照模型的表现特征分类</p></blockquote><p>按照模型的表现特征不同，具体可分为:</p><ul><li>(1)确定性模型和随机性模型:取决于是否考虑随机因素的影响。近年来随着数学的发展， 又有所谓的突变性模型和模糊性模型。</li><li>(2)静态模型和动态模型:取决于是否考虑时间因素引起的变化。</li><li>(3)线性模型和非线性模型:取决于模型的基本关系，如微分方程是否是线性的。</li><li>(4)离散模型和连续模型:指模型中的变量(主要是时间变量)是离散的还是连续的。</li></ul><blockquote><p>按照模型的建模目的分类</p></blockquote><p>按照建模目的不同，可对模型进行分类，如描述模型、预报模型、优化模型、决策模型、控制模型等。</p><blockquote><p>按照对模型结构的了解程度分类</p></blockquote><p>按照对模型结构的了解程度不同，可对模型进行分类，如白箱模型、灰箱模型、黑箱模型。</p><ul><li>白箱主要包括用力学、热学、电学等一些机理相当清楚的学科描述的现象以及相应的工程技术问题，这方面的模型大多已经基本确定，还需深入研究的主要是优化设计和控制等问题。</li><li>灰箱主要指生态、气象、经济、交通等领域的机理尚不十分清楚的现象，在建立和改善模型方面都有不同程度的工作要做。</li><li>至于黑箱则主要指生命科学和社会科学等领域的一些机理(数量关系方面)很不清楚的现象。</li></ul><p>当然，白箱、灰箱、黑箱之间并没有明显的界限，而且随着科学技术的发展，箱子的“颜色”必然是逐渐由暗变亮的。</p>',57)])])}const _=e(p,[["render",o]]);export{s as __pageData,_ as default};
